<script setup lang="ts">
import { computed, ref, watch } from 'vue';
import { ChevronDown, Copy, ExternalLink, Search, WalletCards } from 'lucide-vue-next';
import type { CryptoChain, CryptoConfiguredAsset } from '../lib/cryptoPayments';
import { addressHasAsset, chainExplorer, portfolioAmount, type PortfolioBalance, type PortfolioFilter, type PortfolioSnapshot } from '../lib/cryptoPortfolio';
import { displayWalletAddress, walletAddressAsset } from '../lib/walletPresentation';
import { stamp } from '../lib/commerce';
import { t } from '../i18n';
import WalletAssetMark from './WalletAssetMark.vue';
import {nativeDecimals} from '../lib/cryptoNetworks';
const props = defineProps<{ chain?: CryptoChain; assets: CryptoConfiguredAsset[]; rows: PortfolioBalance[]; snapshot?: PortfolioSnapshot; filter: PortfolioFilter; selected: string[]; writable: boolean; busy: boolean; loading: boolean; loaded: boolean; hasMore: boolean }>();
const emit = defineEmits<{ 'update:filter': [value: PortfolioFilter]; 'update:selected': [value: string[]]; copy: [value: string]; more: []; withdraw: [] }>();
const assetFilter = ref(''), search = ref('');
watch(() => props.assets, values => { if (assetFilter.value && assetFilter.value !== 'native' && !values.some(value => value.id === assetFilter.value)) assetFilter.value = ''; });
const visible = computed(() => props.rows.filter(row => addressHasAsset(row, assetFilter.value) && (!search.value || [row.address, row.order_id, row.label, String(row.index)].some(value => value?.toLowerCase().includes(search.value.toLowerCase())))));
const filters = [{ id: 'funded', label: '有余额', count: 'funded_addresses' }, { id: 'all', label: '全部地址', count: 'total_addresses' }, { id: 'empty', label: '无余额', count: 'empty_addresses' }, { id: 'failed', label: '查询异常', count: 'failed_addresses' }] as const;
const allSelected = computed(() => visible.value.length > 0 && visible.value.every(row => props.selected.includes(row.address_id)));
function select(id: string, checked: boolean) { emit('update:selected', checked ? [...new Set([...props.selected, id])] : props.selected.filter(value => value !== id)); }
function selectPage(checked: boolean) { const ids = visible.value.map(row => row.address_id); emit('update:selected', checked ? [...new Set([...props.selected, ...ids])] : props.selected.filter(value => !ids.includes(value))); }
function count(key: typeof filters[number]['count']) { return props.snapshot?.[key] ?? '—'; }
function mainAsset(row: PortfolioBalance) {
 return walletAddressAsset(row, props.chain?.native_symbol || 'Gas', assetFilter.value, props.assets);
}
</script>
<template>
 <section class="wallet-address-list">
  <header><h4>{{t('收款地址')}}<span>{{snapshot?.total_addresses ?? '—'}}</span></h4><span>{{chain?.name}}</span></header>
  <div class="wallet-address-filters" :aria-label="t('地址余额筛选')"><button v-for="item in filters" :key="item.id" type="button" :aria-pressed="filter===item.id" :class="{active:filter===item.id}" :disabled="busy" @click="emit('update:filter',item.id)">{{t(item.label)}}<span>{{count(item.count)}}</span></button></div>
  <div class="wallet-address-search"><label><Search :size="16"/><input v-model.trim="search" :placeholder="t('搜索已加载的地址、订单或标签')" :aria-label="t('搜索已加载的地址、订单或标签')"/></label><select v-model="assetFilter" :aria-label="t('当前列表币种')"><option value="">{{t('全部币种')}}</option><option value="native">{{chain?.native_symbol}} · Gas</option><option v-for="asset in assets" :key="asset.id" :value="asset.id">{{asset.symbol}}</option></select></div>
  <p v-if="assetFilter||search" class="wallet-list-help">{{t('搜索与币种筛选仅作用于已加载地址，上方数量仍为整钱包统计。')}}</p>
  <div v-if="writable" class="wallet-selection-bar"><label><input type="checkbox" :checked="allSelected" :disabled="busy||!visible.length" @change="selectPage(($event.target as HTMLInputElement).checked)"/>{{t('选择当前列表')}}</label><span>{{t('已选择')}} {{selected.length}}</span><button v-if="selected.length" type="button" :disabled="busy" @click="emit('update:selected',[])">{{t('清空选择')}}</button><button v-if="selected.length" type="button" class="primary" :disabled="busy" @click="emit('withdraw')">{{t('归集选中地址')}}</button></div>
  <p v-if="loading&&!loaded" class="wallet-address-empty" role="status">{{t('正在查询链上余额…')}}</p>
  <div v-else-if="!visible.length" class="wallet-address-empty"><WalletCards :size="30"/><strong>{{t('当前列表没有匹配的地址')}}</strong><p>{{hasMore?t('可继续加载更多地址，或调整筛选条件。'):t('稍后刷新以获取最新链上余额。')}}</p></div>
  <div class="wallet-address-rows"><article v-for="row in visible" :key="row.address_id" :class="{selected:selected.includes(row.address_id)}">
   <div class="wallet-address-main"><label v-if="writable" class="wallet-checkbox-hit"><input type="checkbox" :checked="selected.includes(row.address_id)" :disabled="busy" :aria-label="t('选择地址')+' '+row.index" @change="select(row.address_id,($event.target as HTMLInputElement).checked)"/></label><span class="wallet-address-avatar">{{row.index}}</span><div class="wallet-address-identity"><strong :title="row.label">{{row.label||t('订单收款地址')}}</strong><code :title="row.address">{{displayWalletAddress(row.address)}}</code><span v-if="row.error||row.stale" class="wallet-row-stale">{{row.last_success_at?t('保留最近成功余额'):t('余额尚未确认')}}</span></div><div class="wallet-address-value"><strong>{{mainAsset(row).amount}}</strong><span>{{mainAsset(row).symbol}}</span></div><button type="button" class="wallet-copy-address" :aria-label="t('复制地址')+' '+row.index" @click="emit('copy',row.address)"><Copy :size="16"/></button></div>
   <details class="wallet-address-details"><summary>{{t('地址详情')}}<ChevronDown :size="14"/></summary><div class="wallet-full-address"><code>{{row.address}}</code><a v-if="chainExplorer(chain?.chain_id||0,row.address)" :href="chainExplorer(chain?.chain_id||0,row.address)" target="_blank" rel="noopener noreferrer" :aria-label="t('在区块浏览器查看地址')+' '+row.index"><ExternalLink :size="16"/></a></div><div class="wallet-row-assets"><div><WalletAssetMark :symbol="chain?.native_symbol" :size="24"/><span>{{chain?.native_symbol}} · Gas</span><strong>{{portfolioAmount(row.native_atoms,nativeDecimals(chain))}}</strong></div><div v-for="token in row.tokens" :key="token.asset_id"><WalletAssetMark :symbol="token.symbol" :size="24"/><span>{{token.symbol}}</span><strong>{{portfolioAmount(token.balance_atoms,token.decimals)}}</strong></div></div><dl><div><dt>{{t('派生路径')}}</dt><dd><code>{{row.path}}</code></dd></div><div><dt>{{t('最近成功查询')}}</dt><dd>{{row.last_success_at?stamp(row.last_success_at):'—'}}</dd></div><div><dt>{{t('查询区块')}}</dt><dd>{{row.block_number?'#'+row.block_number:'—'}}</dd></div><div v-if="row.order_id"><dt>{{t('关联订单')}}</dt><dd><RouterLink :to="{path:'/orders',query:{checkout:row.order_id,user_id:row.user_id}}">{{row.order_id}}</RouterLink></dd></div></dl><p v-if="row.error" class="wallet-row-stale">{{t(row.error)}}</p></details>
  </article></div>
  <footer><span>{{t('已加载')}} {{rows.length}} {{t('个地址')}}<template v-if="visible.length!==rows.length"> · {{t('当前显示')}} {{visible.length}}</template></span><button v-if="hasMore" type="button" :disabled="loading" @click="emit('more')">{{loading?t('查询中…'):t('加载更多地址')}}</button></footer>
  <p class="wallet-list-help wallet-address-retention">{{t('订单地址永久保留。创建付款单时自动分配，不会把历史地址重新分配给其他订单。')}}</p>
 </section>
</template>
