;flex:1}.wallet-full-address a{display:grid;place-items:center;min-width:36px;min-height:44px;flex-shrink:0;color:var(--muted)}.wallet-row-assets{display:grid;gap:11px;margin-bottom:18px}.wallet-row-assets>div{display:flex;align-items:center;gap:9px}.wallet-row-assets span{color:var(--secondary);font-size:12px}.wallet-row-assets strong{font-weight:500;max-width:65%;margin-left:auto;overflow-wrap:anywhere;text-align:right;font-size:12px;font-variant-numeric:tabular-nums}.wallet-address-details dl{display:grid;grid-template-columns:1fr 1fr;gap:13px;margin:0;padding-top:13px;border-top:1px solid var(--border)}.wallet-address-details dt{font-size:12px;color:var(--muted)}.wallet-address-details dd{font-size:12px;color:var(--secondary);line-height:1.8;overflow-wrap:anywhere;margin:5px 0 0}.wallet-row-stale{display:block;color:var(--warning);font-size:12px;line-height:1.7;margin-top:4px;overflow-wrap:anywhere}.wallet-address-empty{display:grid;justify-items:center;text-align:center;gap:10px;padding:35px 15px;color:var(--muted);font-size:12px;line-height:1.8;margin:0}.wallet-address-empty strong{font-size:13px;font-weight:500}.wallet-address-empty p{margin:0}.wallet-list-help{font-size:12px;color:var(--muted);line-height:1.8;margin:0}.wallet-address-list>footer{display:flex;justify-content:space-between;align-items:center;gap:12px;flex-wrap:wrap;color:var(--muted);font-size:12px}.wallet-address-list>footer button{min-height:44px;font-size:12px}.wallet-address-retention{margin-top:3px}@media(max-width:650px){.wallet-address-search{grid-template-columns:minmax(0,1fr) 116px}.wallet-address-avatar{display:none}.wallet-address-main{gap:7px}.wallet-address-value{max-width:44%}.wallet-address-value strong{font-size:13px}.wallet-address-identity strong{font-size:12px}.wallet-checkbox-hit{min-width:25px;width:25px}.wallet-copy-address{min-width:36px;width:36px;padding:8px}.wallet-address-details{padding-left:32px}.wallet-address-details dl{grid-template-columns:1fr}.wallet-selection-bar{gap:7px}.wallet-selection-bar .primary{margin-left:0}.wallet-row-assets strong{font-size:12px}}@media(max-width:390px){.wallet-address-search{grid-template-columns:1fr}.wallet-address-list>header>span{font-size:12px}.wallet-address-filters{gap:4px}.wallet-address-filters button{padding:6px 7px}.wallet-address-main{flex-wrap:wrap}.wallet-address-identity{flex-basis:calc(100% - 68px)}.wallet-address-value{margin:6px 44px 3px 32px;max-width:calc(100% - 76px);flex-basis:100%;text-align:left}.wallet-address-value strong,.wallet-address-value span{display:inline}.wallet-address-value span{margin-left:6px}.wallet-copy-address{margin-left:auto}.wallet-address-details{padding-left:0}}
